def _first_positive_decimal(fragment):
    token = ''
    started = False
    for character in fragment:
        if character.isdigit():
            token += character
            started = True
        elif started and character in '.,':
            token += character
        elif started:
            break
    cleaned = token.replace(',', '').rstrip('.')
    if not cleaned:
        return None
    value = float(cleaned)
    return value if value > 0 else None
def _extract_bill_amount(content):
    markers = ('amount paid', 'payment amount', 'total paid', 'grand total', 'total amount', 'amount due', 'bill amount', 'amount', 'total')
    lines = content.splitlines() or [content]
    for marker in markers:
        for line in lines:
            normalized_line = line.lower().replace('_', ' ')
            position = normalized_line.find(marker)
            if position >= 0:
                value = _first_positive_decimal(line[position + len(marker):])
                if value is not None:
                    return value
    raise RuntimeError('Could not extract a positive bill amount from the selected receipt')
